    public static class HenryDavidThoreau
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Let us not underrate the value of a fact; it will one day flower in a truth.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The life that I aspire to live No man proposeth me— No trade upon the street Wears its emblazonry.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "When will the world learn that a million men are of no importance compared with one man?", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Talk of mysteries! — Think of our life in nature, — daily to be shown matter, to come in contact with it, — rocks, trees, wind on our cheeks! The ''solid'' earth! the ''actual'' world! the ''common sense! Contact! Contact! Who'' are we? ''where'' are we?", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The law will never make men free; it is men who have got to make the law free.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "It is not enough to be industrious; so are the ants. What are you industrious about?", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Not that the story need be long, but it will take a long while to make it short.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Men and boys are learning all kinds of trades but how to make ''men'' of themselves. They learn to make houses; but they are not so well housed, they are not so contented in their houses, as the woodchucks in their holes. What is the use of a house if you haven't got a tolerable planet to put it on? — If you cannot tolerate the planet that it is on?", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "If a man believes and expects great things of himself, it makes no odds where you put him, or what you show him ... he will be surrounded by grandeur.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "I am enjoying existence as much as ever, and regret nothing.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "A gun gives you the body, not the bird.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Truth, Goodness, Beauty — those celestial thrins, Continually are born'; e'en now the Universe, With thousand throats, and eke with greener smiles, Its joy confesses at their recent birth.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "That virtue we appreciate is as much ours as another's. We see so much only as we possess.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Poetry — No definition of poetry is adequate unless it be poetry itself. The most accurate analysis by the rarest wisdom is yet insufficient, and the poet will instantly prove it false by setting aside its requisitions. It is indeed all that we do not know. [...] You might as well think to go in pursuit of the rainbow, and embrace it on the next hill, as to embrace the whole of poetry even in thought.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Aeschylus had a clear eye for the commonest things. His genius was only an enlarged common sense. [...] The multitude that thronged the theatre could no doubt go along with him to the end...", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "On the death of a friend, we should consider that the fates through confidence have devolved on us the task of a double living, that we have henceforth to fulfill the promise of our friend's life also, in our own, to the world.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "An early morning walk is a blessing for the whole day.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Have no mean hours, but be grateful for every hour, and accept what it brings. The reality will make any sincere record respectable. [...] Let the daily tide leave some deposit on these pages, as it leaves sand and shells on the shore.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Who looks in the sun will see no light else; but also he will see no shadow. Our life revolves unceasingly, but the centre is ever the same, and the wise will regard only the seasons of the soul.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "We are as much as we see. Faith is sight and knowledge. The hands only serve the eyes.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "It is a great art to saunter.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "One cannot too soon forget his errors and misdemeanors. To dwell long upon them is to add to the offense. Repentance and sorrow can only be displaced by something better, which is as free and original as if they had not been.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "For many years I was self-appointed inspector of snowstorms and rainstorms, and did my duty faithfully, though I never received one cent for it.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Disobedience is the true foundation of liberty. The obedient must be slaves.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Men go to a fire for entertainment. When I see how eagerly men will run to a fire, whether in warm or in cold weather, by day or by night, dragging an engine at their heels, I'm astonished to perceive how good a purpose the level of excitement is made to serve.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "How vain it is to sit down to write when you have not stood up to live.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Nothing is so much to be feared as fear. Atheism may comparatively be popular with God himself.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The bluebird carries the sky on his back.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The perception of beauty is a moral test.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Fire is the most tolerable third party.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Some circumstantial evidence is very strong, as when you find a trout in the milk.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Nature is full of genius, full of the divinity; so that not a snowflake escapes its fashioning hand.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "That man is the richest whose pleasures are the cheapest.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "It is in vain to dream of a wildness distant from ourselves.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The savage in man is never quite eradicated.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Any fool can make a rule And every fool will mind it.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "I heartily accept the motto, \"That government is best which governs least\"; and I should like to see it acted up to more rapidly and systematically. Carried out, it finally amounts to this, which also I believe — \"That government is best which governs not at all\"; and when men are prepared for it, that will be the kind of government which they will have.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "To speak practically and as a citizen, unlike those who call themselves no-government men, I ask for, not at once no government, but at once a better government. Let every man make known what kind of government would command his respect, and that will be one step toward obtaining it.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Must the citizen ever for a moment, or in the least degree, resign his conscience to the legislator? Why has every man a conscience, then? I think that we should be men first, and subjects afterward. It is not desirable to cultivate a respect for the law, so much as for the right. The only obligation which I have a right to assume is to do at any time what I think right.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Law never made men a whit more just; and, by means of their respect for it, even the well-disposed are daily made the agents of injustice.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "When a sixth of the population of a nation which has undertaken to be the refuge of liberty are slaves, and a whole country is unjustly overrun and conquered by a foreign army, and subjected to military law, I think that it is not too soon for honest men to rebel and revolutionize. What makes this duty the more urgent is the fact that the country so overrun is not our own, but ours is the invading army.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Any man more right than his neighbors constitutes a majority of one.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Thus the state never intentionally confronts a man's sense, intellectual or moral, but only his body, his senses. It is not armed with superior wit or honesty, but with superior physical strength.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "When I meet a government which says to me, ‘Your money or your life,’ why should I be in haste to give it my money?", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "I am as desirous of being a good neighbor as I am of being a bad subject.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "They who know of no purer sources of truth, who have traced up its stream no higher, stand, and wisely stand, by the Bible and the Constitution, and drink at it there with reverence and humility; but they who behold where it comes trickling into this lake or that pool, gird up their loins once more, and continue their pilgrimage toward its fountain-head.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "For eighteen hundred years, though perchance I have no right to say it, the New Testament has been written; yet where is the legislator who has wisdom and practical talent enough to avail himself of the light which it sheds on the science of legislation?", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The progress from an absolute to a limited monarchy, from a limited monarchy to a democracy, is a progress toward a true respect for the individual.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The rich man... is always sold to the institution which makes him rich.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "if it is of such a nature that it requires you to be the agent of injustice to another, then I say, break the law. Let your life be a counter-friction to stop the machine.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "There will never be a really free and enlightened State until the State comes to recognize the individual as a higher and independent power, from which all its own power and authority are derived, and treats him accordingly.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "A State which bore this kind of fruit, and suffered it to drop off as fast as it ripened, would prepare the way for a still more perfect and glorious State, which also I have imagined, but not yet anywhere seen.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "To some extent, mythology is only the most ancient history and biography. So far from being false or fabulous in the common sense, it contains only enduring and essential truth, the I and you, the here and there, the now and then, being omitted.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "In the mythus a superhuman intelligence uses the unconscious thoughts and dreams of men as its hieroglyphics to address men unborn. In the history of the human mind, these glowing and ruddy fables precede the noonday thoughts of men, as Aurora the sun's rays.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "You can hardly convince a man of an error in a lifetime, but must content yourself with the reflection that the progress of science is slow. If he is not convinced, his grandchildren may be.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Men reverence one another, not yet God.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "I trust that some may be as near and dear to Buddha, or Christ, or Swedenborg, who are without the pale of their churches. It is necessary not to be Christian to appreciate the beauty and significance of the life of Christ.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The wisest man preaches no doctrines; he has no scheme; he sees no rafter, not even a cobweb, against the heavens. It is clear sky.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Some old poet's grand imagination is imposed on us as adamantine everlasting truth, and God's own word!", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "It is remarkable that, notwithstanding the universal favor with which the New Testament is outwardly received, and even the bigotry with which it is defended, there is no hospitality shown to, there is no appreciation of, the order of truth with which it deals.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "It would be worthy of the age to print together the collected Scriptures or Sacred Writings of the several nations, the Chinese, the Hindus, the Persians, the Hebrews, and others, as the Scripture of mankind.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The mass of men lead lives of quiet desperation. What is called resignation is confirmed desperation.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Most of the luxuries, and many of the so-called comforts of life, are not only not indispensable, but positive hindrances to the elevation of mankind.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Men remain in their present low and primitive condition; but if they should feel the influence of the spring of springs arousing them, they would of necessity rise to a higher and more ethereal life.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Our inventions are wont to be pretty toys, which distract our attention from serious things. They are but improved means to an unimproved end, an end which it was already but too easy to arrive at.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "If I knew for a certainty that a man was coming to my house with the conscious design of doing me good, I should run for my life.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "There are a thousand hacking at the branches of evil to one who is striking at the root, and it may be that he who bestows the largest amount of time and money on the needy is doing the most by his mode of life to produce that misery which he strives in vain to relieve.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "I wanted to live deep and suck out all the marrow of life, to live so sturdily and Spartan-like as to put to rout all that was not life, to cut a broad swath and shave close, to drive life into a corner, and reduce it to its lowest terms, and, if it proved to be mean, why then to get the whole and genuine meanness of it, and publish its meanness to the world; or if it were sublime, to know it by experience, and be able to give a true account of it in my next excursion.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Simplify, simplify.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "If one advances confidently in the direction of his dreams, and endeavors to live the life which he has imagined, he will meet with a success unexpected in common hours ... In proportion as he simplifies his life, the laws of the universe will appear less complex, and solitude will not be solitude, nor poverty poverty, nor weakness weakness.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "A living dog is better than a dead lion. Shall a man go and hang himself because he belongs to the race of pygmies, and not be the biggest pygmy that he can? Let every one mind his own business, and endeavor to be what he was made. If a man does not keep pace with his companions, perhaps it is because he hears a different drummer. Let him step to the music which he hears, however measured or far away.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Money is not required to buy one necessity of the soul.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Only that day dawns to which we are awake. There is more day to dawn. The sun is but a morning star.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "It takes two to speak the truth, — one to speak, and another to hear.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "This world is but canvas to our imaginations.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Dreams are the touchstones of our characters.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Go where we will on the ''surface'' of things, men have been there before us.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The frontiers are not east or west, north or south, but wherever a man ''fronts'' a fact, though that fact be his neighbor, there is an unsettled wilderness between him and Canada, between him and the setting sun, or, farther still, between him and ''it''.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "A true account of the actual is the rarest poetry, for common sense always takes a hasty and superficial view.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Poetry is the mysticism of mankind.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "The unconsciousness of man is the consciousness of God.", Author = "Henry David Thoreau" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Henry_David_Thoreau", Text = "My life has been the poem I would have writ, But I could not both live and utter it.", Author = "Henry David Thoreau" },
        };
    }
}